/**
 * P25-11: Tool Input Streaming
 * Progressive tool input rendering with callbacks.
 *
 * Enables streaming partial tool inputs to the UI as they're being
 * generated by the LLM, rather than waiting for the complete input.
 *
 * Usage:
 *   const stream = createToolInputStream(env, {
 *     onInputPart: (part) => updateUI(part),
 *     onComplete: (input) => finalizeUI(input)
 *   });
 *   await stream.push({ type: 'text', content: '{"city":' });
 *   await stream.push({ type: 'text', content: '"Paris"}' });
 *   await stream.complete();
 */

// =============================================================================
// Tool Input Stream Types
// =============================================================================

/**
 * @typedef {'text' | 'json' | 'partial'} InputChunkType
 */

/**
 * @typedef {Object} InputChunk
 * @property {string} toolCallId - Tool call ID
 * @property {string} toolName - Tool name
 * @property {InputChunkType} type - Chunk type
 * @property {string} content - Partial content
 * @property {number} index - Chunk index
 * @property {number} timestamp - Unix ms timestamp
 */

/**
 * @typedef {Object} ToolInputStreamOptions
 * @property {(chunk: InputChunk) => void} [onInputPart] - Callback for each chunk
 * @property {(toolName: string, input: any) => void} [onComplete] - Callback when input complete
 * @property {(error: Error) => void} [onError] - Callback for errors
 * @property {number} [bufferSize] - Max chunks to buffer before flushing
 * @property {number} [flushIntervalMs] - Auto-flush interval (0 = manual only)
 */

/**
 * @typedef {Object} ToolInputStreamState
 * @property {string} toolCallId
 * @property {string} toolName
 * @property {InputChunk[]} chunks
 * @property {string} accumulated
 * @property {boolean} complete
 * @property {number} index
 */

// =============================================================================
// Tool Input Stream
// =============================================================================

export class ToolInputStream {
  /**
   * @param {ToolInputStreamOptions} options
   */
  constructor(options = {}) {
    /** @type {(chunk: InputChunk) => void} */
    this.onInputPart = options.onInputPart || (() => {});
    /** @type {(toolName: string, input: any) => void} */
    this.onComplete = options.onComplete || (() => {});
    /** @type {(error: Error) => void} */
    this.onError = options.onError || (() => {});
    /** @type {number} */
    this.bufferSize = options.bufferSize || 10;
    /** @type {number} */
    this.flushIntervalMs = options.flushIntervalMs || 0;

    /** @type {Map<string, ToolInputStreamState>} */
    this.streams = new Map();
    /** @type {ReturnType<typeof setTimeout> | null} */
    this.flushTimer = null;

    if (this.flushIntervalMs > 0) {
      this.startAutoFlush();
    }
  }

  /**
   * Create or get a stream for a tool call.
   * @param {string} toolCallId
   * @param {string} toolName
   * @returns {ToolInputStreamState}
   */
  createStream(toolCallId, toolName) {
    if (this.streams.has(toolCallId)) {
      return this.streams.get(toolCallId);
    }

    const state = {
      toolCallId,
      toolName,
      chunks: [],
      accumulated: '',
      complete: false,
      index: 0,
    };
    this.streams.set(toolCallId, state);
    return state;
  }

  /**
   * Push a chunk to a tool call stream.
   * @param {string} toolCallId
   * @param {string} toolName
   * @param {string} content
   * @param {InputChunkType} [type='text']
   * @returns {Promise<InputChunk>}
   */
  async push(toolCallId, toolName, content, type = 'text') {
    let state = this.streams.get(toolCallId);
    if (!state) {
      state = this.createStream(toolCallId, toolName);
    }

    if (state.complete) {
      throw new Error(`Stream for tool call ${toolCallId} already completed`);
    }

    const chunk = {
      toolCallId,
      toolName,
      type,
      content,
      index: state.index++,
      timestamp: Date.now(),
    };

    state.chunks.push(chunk);
    state.accumulated += content;

    this.onInputPart(chunk);

    return chunk;
  }

  /**
   * Mark a tool call stream as complete.
   * @param {string} toolCallId
   * @returns {Promise<any>} Parsed input
   */
  async complete(toolCallId) {
    const state = this.streams.get(toolCallId);
    if (!state) {
      throw new Error(`No stream found for tool call ${toolCallId}`);
    }

    state.complete = true;

    // Try to parse as JSON
    let input;
    try {
      input = JSON.parse(state.accumulated);
    } catch {
      input = state.accumulated;
    }

    this.onComplete(state.toolName, input);

    return input;
  }

  /**
   * Get the accumulated input for a tool call.
   * @param {string} toolCallId
   * @returns {string}
   */
  getAccumulated(toolCallId) {
    const state = this.streams.get(toolCallId);
    return state?.accumulated || '';
  }

  /**
   * Get the parsed input for a tool call.
   * @param {string} toolCallId
   * @returns {any}
   */
  getParsedInput(toolCallId) {
    const accumulated = this.getAccumulated(toolCallId);
    if (!accumulated) return null;

    try {
      return JSON.parse(accumulated);
    } catch {
      return accumulated;
    }
  }

  /**
   * Check if a tool call is complete.
   * @param {string} toolCallId
   * @returns {boolean}
   */
  isComplete(toolCallId) {
    const state = this.streams.get(toolCallId);
    return state?.complete || false;
  }

  /**
   * Reset the stream for a tool call.
   * @param {string} toolCallId
   */
  reset(toolCallId) {
    this.streams.delete(toolCallId);
  }

  /**
   * Reset all streams.
   */
  resetAll() {
    this.streams.clear();
    if (this.flushTimer) {
      clearInterval(this.flushTimer);
      this.flushTimer = null;
    }
  }

  /**
   * Start auto-flush timer.
   */
  startAutoFlush() {
    if (this.flushTimer) return;

    this.flushTimer = setInterval(() => {
      // Flush logic would go here if we had a buffer
      // For now, this is a no-op as we flush on each push
    }, this.flushIntervalMs);
  }

  /**
   * Stop auto-flush timer.
   */
  stopAutoFlush() {
    if (this.flushTimer) {
      clearInterval(this.flushTimer);
      this.flushTimer = null;
    }
  }

  /**
   * Get stats for all streams.
   * @returns {{ active: number, complete: number, totalChunks: number }}
   */
  getStats() {
    let active = 0;
    let complete = 0;
    let totalChunks = 0;

    for (const state of this.streams.values()) {
      if (state.complete) {
        complete++;
      } else {
        active++;
      }
      totalChunks += state.chunks.length;
    }

    return { active, complete, totalChunks };
  }
}

// =============================================================================
// Convenience Functions
// =============================================================================

/**
 * Create a tool input stream.
 * @param {ToolInputStreamOptions} options
 * @returns {ToolInputStream}
 */
export function createToolInputStream(options) {
  return new ToolInputStream(options);
}

/**
 * Create a tool input stream with console logging.
 * @param {ToolInputStreamOptions} [extraOptions]
 * @returns {ToolInputStream}
 */
export function createLoggingToolInputStream(extraOptions = {}) {
  return createToolInputStream({
    onInputPart: (chunk) => {
      console.log(`[ToolInput] ${chunk.toolName} chunk ${chunk.index}: ${chunk.content}`);
    },
    onComplete: (toolName, input) => {
      console.log(`[ToolInput] ${toolName} complete:`, input);
    },
    onError: (error) => {
      console.error('[ToolInput] Error:', error);
    },
    ...extraOptions,
  });
}
